import os

def transform(grid):
    new_grid = [row[:] for row in grid]

    # Find shapes (top rows with 5s)
    first = {}
    last = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 5:
                if r not in first:
                    first[r] = c
                last[r] = c

    segments = []

    # Draw segments and fill interiors for each shape
    for r_top in sorted(first.keys()):
        c_left = first[r_top]
        c_right = last[r_top]
        n = c_right - c_left + 1  # width

        # Segment goes n+1 cells wide at r_top-1
        segment_row = r_top - 1
        segment_col_start = c_left - 1
        n_seg = n + 1  # 5 cells for n=4

        for c in range(segment_col_start, segment_col_start + n_seg):
            if 0 <= c < len(grid[0]):
                if 0 <= segment_row < len(grid):
                    new_grid[segment_row][c] = 2
                else:
                    # If segment row is outside grid, check if it was within bounds
                    pass

        # Fill interior (preserve 5s)
        for r in range(r_top + 1, c_left + 4):  # intersects vertically
            if r in first:
                for c in range(c_left + 1, c_right):
                    if grid[r][c] == 0:
                        new_grid[r][c] = 2

    return new_grid

