import os, json

def transform(grid):
    new_grid = [row[:] for row in grid]

    # Find shapes
    first = {}
    last = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 5:
                if r not in first:
                    first[r] = c
                last[r] = c

    # Track which shapes exist (to determine segment positions correctly)
    shape_rows = sorted(first.keys())

    for r_top in shape_rows:
        c_left = first[r_top]
        c_right = last[r_top]

        # Find bottom row
        r_bottom = None
        for r in range(r_top, len(grid)):
            if r in last and last[r] == c_right:
                r_bottom = r
                break
        if r_bottom is None:
            continue

        # Find segment row for this shape
        # Need to check if a previous shape has a segment in this row
        seg_row = None
        for prev_r in shape_rows:
            if prev_r > r_top:
                c_prev_left = first[prev_r]
                c_prev_right = last[prev_r]
                seg_row = (prev_r + 1)  # segment for prev shape
                break

        # Draw segment above the shape
        if seg_row is None:
            seg_row = r_top - 1
        seg_col_start = -1

        # Segment is 5 cells wide starting at c_left - 1
        n_seg = 4  # width of interior
        for c in range(seg_col_start, seg_col_start + n_seg + 1):
            if 0 <= c < len(grid[0]) and 0 <= seg_row < len(grid):
                new_grid[seg_row][c] = 2

        # Fill interior: rows 1-2 inside the shape, preserve 5s, 0s -> 2s
        for r_fill in range(r_top + 1, min(r_bottom + 1, len(grid))):
            if r_fill < r_bottom:  # skip bottom row
                for c_fill in range(c_left + 1, c_right):
