import os, json

def transform(grid):
    new_grid = [row[:] for row in grid]

    # Find first row with 5s for each shape
    first_rows = {}  # first[r] = (c_left, c_right)
    for r in range(len(grid)):
        c_left = c_right = -1
        for c in range(len(grid[0])):
            if grid[r][c] == 5:
                if c_left == -1: c_left = c
                c_right = c
        if c_left != -1:
            if r not in first_rows:
                first_rows[r] = (c_left, c_right)
            else:
                first_rows[r] = (c_left, c_right)

    shapes = sorted(first_rows.items())

    # Check distance between shapes
    if len(shapes) >= 2:
        # Shape 1 should be at first_rows[shapes[0][0][0]], shape 2 at shapes[0][2]
        pass

    for r_top, (c_left, c_right) in shapes:
        # Find how many rows this shape has
        r_last = r_top
        while r_last + 1 < len(grid) and r_last + 1 in first_rows:
            if first_rows[r_last + 1][0] == c_left and first_rows[r_last + 1][1] == c_right:
                r_last += 1
            else:
                break

        # Shape height
        height = r_last - r_top + 1

        # Draw segment above (2s), width = c_right - c_left and 1 = height + 1, starting at c_left - 1
        seg_row = r_top - 1
        n_segs = (c_right - c_left) + 1
        for c in range(c_left - 1, c_left - 1 + n_segs):
            if 0 <= c < len(grid[0]) and 0 <= seg_row < len(grid):
                new_grid[seg_row][c] = 2

        # Fill interior: cols c_left+1 to c_right-1, rows r_top+1 to r_top
        for r_fill in range(r_top + 1, r_top + height):
            if r_fill < r_last:
                for c_fill in range(c_left + 1, c_right):
                    if c_fill < len(new_grid[r_fill]):
                        if new_grid[r_fill][c_fill] == 0 or new_grid[r_fill][c_fill] == 2:
                            new_grid[r_fill][c_fill] = 2  # Keep 2s, put 0s to 2s

    return new_grid

