def transform_grid(grid):
    new_grid = [row[:] for row in grid]

    # Find shape
    shape_rows = {}
    for r in range(len(grid)):
        c_left = c_right = -1
        for c in range(len(grid[0])):
            if grid[r][c] == 5:
                if c_left == -1: c_left = c
                c_right = c
        if c_left != -1:
            shape_rows[r] = (c_left, c_right)

    if not shape_rows:
        return new_grid

    r_top = min(shape_rows.keys())
    r_bottom = max(shape_rows.keys())
    c_left, c_right = shape_rows[r_top]  # Assuming constant span

    bottom_is_solid = is_bottom_row(grid, r_top, r_bottom, c_left, c_right)

    # Determine segment row
    # If solid bottom: segment at r_top, shift shape down
    # If non-solid bottom: segment at r_top-1, keep shape in place
    if bottom_is_solid:
        seg_row = r_top
        shift = 1  # Shape shifts down
        actual_r_top = r_top + shift
        actual_r_bottom = r_bottom + shift
    else:
        seg_row = r_top - 1
        shift = 0
        actual_r_top = r_top
        actual_r_bottom = r_bottom

    # Copy all 5s and 0s from input to new positions
    for r in range(r_top, r_bottom + 1):
        for c in range(c_left, c_right + 1):
            dst_r = r + shift
            if 0 <= dst_r < len(new_grid):
                new_grid[dst_r][c] = grid[r][c]

    # Handle bottom row if shifted (preserve the solid bottom)
    if shift == 1:
        # Input bottom row was solid, ensure it's preserved
        for c in range(c_left, c_right + 1):
            new_grid[actual_r_bottom][c] = 5
    else:
        # Non-solid bottom: the "gap" row needs to have gaps filled
        # The last input row is at r_bottom, which becomes actual_r_bottom
        for c in range(c_left + 1, c_right):
            if new_grid[actual_r_bottom][c] == 0:
                new_grid[actual_r_bottom][c] = 2

        # Also add a new filled bottom row at r_bottom + 1
        for c in range(c_left, c_right + 1):
            if 0 <= r_bottom + 1 < len(new_grid):
                new_grid[r_bottom + 1][c] = 5

    # Fill interior (excluding bottom row)
    for r in range(actual_r_top, actual_r_bottom):
        for c in range(c_left + 1, c_right):
            if new_grid[r][c] == 0:
                new_grid[r][c] = 2

    # Draw segment at seg_row, from c_left-2 to c_right-1
    seg_start = c_left - 2
    seg_end = c_right - 1
    for c in range(seg_start, seg_end + 1):
        if 0 <= c < len(grid[0]) and 0 <= seg_row < len(new_grid):
            new_grid[seg_row][c] = 2

    return new_grid

