    sorted_rows = sorted(shape_rows.keys())

    i = 0
    while i < len(sorted_rows):
        r_top = sorted_rows[i]
        c_left, c_right = shape_rows[r_top]

        shape_indices = [sorted_rows[i]]
        i += 1
        while i < len(sorted_rows) and shape_rows[sorted_rows[i]] == (c_left, c_right):
            shape_indices.append(sorted_rows[i])
            i += 1

        r_bottom = shape_indices[-1]

        # Check if bottom is SOLID (all 5s in span)
        is_bottom_solid = all(grid[r_bottom][c] == 5 for c in range(c_left, c_right + 1))

        if is_bottom_solid:
            seg_row = r_top  # Segment at r_top
            shift = 1        # Shift down
        else:
            seg_row = r_top - 1  # Just above r_top
            shift = 0

        # Step 1: Clear 5s at original seg_row, within shape column span
        if 0 <= seg_row < len(new_grid):
            for c in range(c_left, c_right + 1):
