        seg_end = min(len(grid[0]) - 1, c_right - 1)
        if 0 <= seg_row < len(new_grid):
            for c in range(seg_start, seg_end + 1):
                new_grid[seg_row][c] = 2

        # Step 3: Copy shape to shifted/new position
        actual_top = r_top + shift
        actual_bottom = r_bottom + shift

        for r in range(r_top, r_bottom + 1):
            for c in range(c_left, c_right + 1):
                dst_r = r + shift
                if 0 <= dst_r < len(new_grid):
                    new_grid[dst_r][c] = grid[r][c]

        # Step 4: Fill interior with 2s (except bottom row)
        for r in range(actual_top, actual_bottom):
